var _topProgressTimer = null;
function setTopProgress(pct) {
  var b = $('top-progress');
  if (!b) return;
  if (pct === 0) {
    b.style.opacity = '1';
    b.style.width = '0%';
  } else if (pct === 100) {
    b.style.width = '100%';
    setTimeout(function () {
      b.style.opacity = '0';
      setTimeout(function () { b.style.width = '0%'; }, 250);
    }, 200);
  } else {
    b.style.opacity = '1';
    b.style.width = pct + '%';
  }
}
function startTopProgress() {
  setTopProgress(18);
  clearInterval(_topProgressTimer);
  var current = 18;
  _topProgressTimer = setInterval(function () {
    if (current < 85) {
      current += Math.random() * 14;
      setTopProgress(Math.min(current, 85));
    }
  }, 140);
}
function finishTopProgress() {
  clearInterval(_topProgressTimer);
  setTopProgress(100);
}

function busy(on, text) {
  var el = $('loading');
  if (!el) return;
  var txt = $('loading-text');
  if (txt) txt.textContent = text || 'লোড হচ্ছে…';
  if (on) {
    startTopProgress();
    el.classList.add('show');
    el.style.display = 'flex';
  } else {
    finishTopProgress();
    el.classList.remove('show');
    setTimeout(function () {
      if (!el.classList.contains('show')) el.style.display = 'none';
    }, 220);
  }
}

function call(action, data, okMsg) {
  busy(1, 'প্রক্রিয়াধীন…');
  return api(action, data).then(function (r) { busy(0); if (!r.ok) { toast(r.err || 'সমস্যা হয়েছে', 1); throw new Error(r.err); } if (okMsg) toast(okMsg); return r; })
    .catch(function (e) { busy(0); if (e && e.message && !/সমস্যা|মেলেনি|মেয়াদ/.test(e.message) && !$('toast').classList.contains('show')) toast(e.message || 'সার্ভারে পৌঁছানো যাচ্ছে না', 1); throw e; });
}
function toast(m, err) { var t = $('toast'); t.textContent = m; t.className = 'toast show' + (err ? ' err' : ''); clearTimeout(t._t); t._t = setTimeout(function () { t.className = 'toast'; }, err ? 5000 : 2400); }
function load(tabs, force) {
  var need = tabs.filter(function (t) { return force || !A.data[t]; });
  if (!need.length) return Promise.resolve();
  startTopProgress();
  return api('a_data', { tabs: need }).then(function (r) {
    finishTopProgress();
    if (!r.ok) throw new Error(r.err);
    fixImgs(r);
    need.forEach(function (t) { A.data[t] = r[t] || []; });
    A.eps = r.eps;
    A.cloudinary = r.cloudinary;
    A.sms = r.sms;
    A.brevo = r.brevo;
    A.webapp = r.webapp;
  }).catch(function (e) {
    finishTopProgress();
    toast(e.message || 'লোড করা যায়নি', 1);
    throw e;
  });
}
function kv(t) { var o = {}; (A.data[t] || []).forEach(function (r) { o[r.key] = r.value; }); return o; }

// --- ৪. মডাল ও কনফার্ম ডায়ালগ ---
var _modalCloseTimer = null;
function modal(h, wide) {
  clearTimeout(_modalCloseTimer);
  var ov = $('mov'), bx = $('mbox');
  if (!ov || !bx) return;

  var tmp = document.createElement('div');
  tmp.innerHTML = h;

  // যদি পুরো কন্টেন্ট একটি র‍্যাপার div-এর ভেতর থাকে তবে সেটি খুলে নেওয়া
  if (tmp.children.length === 1 && tmp.firstElementChild.tagName === 'DIV' && tmp.firstElementChild.querySelector('h3')) {
    var inner = tmp.firstElementChild;
    while (inner.firstChild) tmp.appendChild(inner.firstChild);
    tmp.removeChild(inner);
  }

  var head = document.createElement('div');
  head.className = 'mhead';
  var headTxt = document.createElement('div');
  headTxt.className = 'mhead-txt';

  var h3 = tmp.querySelector('h3');
  if (h3) {
    var nextEl = h3.nextElementSibling;
    headTxt.appendChild(h3);
    if (nextEl && nextEl.tagName === 'P') {
      nextEl.removeAttribute('style');
      headTxt.appendChild(nextEl);
    }
  }
  head.appendChild(headTxt);

  var closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'mclose';
  closeBtn.setAttribute('aria-label', 'বন্ধ করুন');
  closeBtn.setAttribute('title', 'বন্ধ করুন (Esc)');
  closeBtn.innerHTML = I.x;
  closeBtn.onclick = closeModal;
  head.appendChild(closeBtn);

  var foot = null;
  var macts = tmp.querySelector('.macts');
  if (macts) {
    foot = document.createElement('div');
    foot.className = 'mfoot';
    while (macts.firstChild) foot.appendChild(macts.firstChild);
    if (macts.parentNode) macts.parentNode.removeChild(macts);
  }

  var body = document.createElement('div');
  body.className = 'mbody';
  while (tmp.firstChild) body.appendChild(tmp.firstChild);

  bx.innerHTML = '';
  bx.className = 'mbox' + (wide === 'sm' ? ' sm' : (wide ? ' wide' : ''));
  bx.appendChild(head);
  if (body.childNodes.length) bx.appendChild(body);
  if (foot) bx.appendChild(foot);
  body.scrollTop = 0;

  ov.hidden = false;
  document.body.classList.add('modal-open');
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      ov.classList.add('open');
    });
  });
  var f = body.querySelector('input:not([type=checkbox]):not([type=hidden]),textarea');
  if (f) setTimeout(function () { try { f.focus(); } catch (e) {} }, 90);
}
function closeModal() {
  var ov = $('mov'), bx = $('mbox');
  if (!ov || ov.hidden) return;
  ov.classList.remove('open');
  document.body.classList.remove('modal-open');
  clearTimeout(_modalCloseTimer);
  _modalCloseTimer = setTimeout(function () {
    if (!ov.classList.contains('open')) {
      ov.hidden = true;
      if (bx) bx.innerHTML = '';
    }
  }, 190);
}
function confirmBox(title, text, yesTxt, fn, danger, typeMatch) {
  if (typeMatch) return typeConfirmBox(title, text, typeMatch, yesTxt, fn, danger);
  modal('<h3>' + title + '</h3><p>' + text + '</p><div class="macts"><a class="btn sm sec" onclick="closeModal()">বাতিল</a><a class="btn sm' + (danger ? ' red' : '') + '" id="myes">' + yesTxt + '</a></div>', 'sm');
  $('myes').onclick = function () { closeModal(); fn(); };
}
function typeConfirmBox(title, text, targetPhrase, yesTxt, fn, danger) {
  var target = String(targetPhrase || 'DELETE').trim();
  var html = '<h3>' + title + '</h3>' +
    '<p style="color:var(--mut);font-size:13.5px;line-height:1.55;margin:8px 0 14px">' + text + '</p>' +
    '<div class="vconf-box">' +
      '<label class="vconf-label">নিশ্চিত করতে নিচে হুবহু <b class="vconf-target">' + esc(target) + '</b> লিখুন:</label>' +
      '<input class="in vconf-in" id="vconf_in" placeholder="' + esc(target) + '" autocomplete="off" spellcheck="false">' +
    '</div>' +
    '<div class="macts" style="margin-top:18px">' +
      '<a class="btn sm sec" onclick="closeModal()">বাতিল</a>' +
      '<button type="button" class="btn sm' + (danger ? ' red' : '') + '" id="myes" disabled style="opacity:0.35;cursor:not-allowed;pointer-events:none">' + yesTxt + '</button>' +
    '</div>';
  modal(html, 'sm');
  var inp = $('vconf_in');
  var btn = $('myes');
  if (!inp || !btn) return;
  function checkMatch() {
    var val = (inp.value || '').trim();
    var isMatch = (val.toLowerCase() === target.toLowerCase()) || (val.toUpperCase() === 'DELETE');
    if (isMatch) {
      btn.disabled = false;
      btn.style.opacity = '1';
      btn.style.cursor = 'pointer';
      btn.style.pointerEvents = 'auto';
    } else {
      btn.disabled = true;
      btn.style.opacity = '0.35';
      btn.style.cursor = 'not-allowed';
      btn.style.pointerEvents = 'none';
    }
  }
  inp.oninput = checkMatch;
  inp.onkeydown = function (e) {
    if (e.key === 'Enter') {
      var val = (inp.value || '').trim();
      var isMatch = (val.toLowerCase() === target.toLowerCase()) || (val.toUpperCase() === 'DELETE');
      if (isMatch && !btn.disabled) {
        e.preventDefault();
        closeModal();
        fn();
      }
    }
  };
  btn.onclick = function () {
    if (btn.disabled) return;
    closeModal();
    fn();
  };
}

