function lImgUrl(i, k) {
  var cur = A.edit.rows[i][k] || '';
  modal('<h3>পোস্টের ছবির লিঙ্ক (URL)</h3><p style="margin-top:4px">সরাসরি ছবির লিঙ্ক পেস্ট করুন অথবা Cloudinary-তে আপলোড করুন:</p>' +
    '<div class="fl" style="margin-top:12px"><label><span>ইমেজ URL</span></label><input class="in" id="m_post_img" value="' + esc(cur) + '" placeholder="https://res.cloudinary.com/... বা https://example.com/pic.jpg"></div>' +
    '<div class="macts">' +
      '<a class="btn sm sec" onclick="closeModal()">বাতিল</a>' +
      '<a class="btn sm sec" id="m_post_cld">' + I.upl + 'Cloudinary-তে তুলুন</a>' +
      '<a class="btn sm" id="m_post_set">লিঙ্ক সেট করুন</a>' +
    '</div>');
  $('m_post_set').onclick = function () {
    var u = ($('m_post_img').value || '').trim();
    A.edit.rows[i][k] = u;
    setDirty();
    closeModal();
    lDraw();
  };
  $('m_post_cld').onclick = function () {
    var u = ($('m_post_img').value || '').trim();
    if (!u) return toast('লিঙ্ক লিখুন', 1);
    if (!/^https?:\/\//i.test(u)) return toast('সঠিক লিঙ্ক (https://...) দিন', 1);
    closeModal();
    var sub = (A.edit && A.edit.t) || 'posts';
    uploadUrl(u, function (cloudUrl) {
      A.edit.rows[i][k] = cloudUrl;
      setDirty();
      lDraw();
    }, sub, cur);
  };
}
function lImgClear(i, k) {
  A.edit.rows[i][k] = '';
  setDirty();
  lDraw();
}
function lSave() {
  var E = A.edit, L = LISTS[E.t];
  var rows = E.rows.map(function (r, i) { var o = {}; L.cols.forEach(function (c) { o[c[0]] = r[c[0]] == null ? '' : String(r[c[0]]).trim(); }); if (L.order) o.order = String(i + 1); return o; });
  var keyCol = L.lockName || L.cols[0][0], seen = {}, dup = null, empty = null;
  rows.forEach(function (r) { var k = r[keyCol]; if (!k && L.cols.some(function (c) { return r[c[0]]; })) empty = true; if (k && seen[k]) dup = k; seen[k] = 1; });
  if (empty) return toast('"' + L.cols.filter(function (c) { return c[0] === keyCol; })[0][1] + '" খালি রাখা যাবে না', 1);
  if (dup) return toast('"' + dup + '" দুইবার আছে', 1);
  call('a_save', { tab: E.t, rows: rows }, 'সেভ হয়েছে ✓').then(function () { A.dirty = false; A.data[E.t] = null; render(E.t); }).catch(function () {});
}

