window.updateSmsTplPreview = function () {
  var tplEl = $('sms_template');
  var prevEl = $('sms_tpl_preview');
  var lenEl = $('sms_tpl_len');
  if (!tplEl || !prevEl) return;
  var val = (tplEl.value || '').trim() || 'উদ্যোক্তা গ্রাফিক্স AI তে আপনার ওটিপি কোড: {otp}। মেয়াদ ৫ মিনিট।';
  var sample = val.indexOf('{otp}') > -1 ? val.replace(/\{otp\}/g, '1234') : (val + ' 1234');
  prevEl.textContent = sample;
  if (lenEl) lenEl.textContent = sample.length + ' অক্ষর';
};

window.saveSms = function () {
  var tokenIn = ($('sms_token') ? $('sms_token').value : '').trim();
  var senderIn = ($('sms_sender') ? $('sms_sender').value : '').trim();
  var urlIn = ($('sms_url') ? $('sms_url').value : '').trim();
  var tplIn = ($('sms_template') ? $('sms_template').value : '').trim();

  var finalToken = (tokenIn && tokenIn.indexOf('••••') !== 0) ? tokenIn : '';
  if (!finalToken && !(A.sms && A.sms.ready)) {
    return toast('BulkSMSBD API Key পূরণ করুন', 1);
  }

  var finalSender = senderIn;
  var finalUrl = urlIn || 'https://bulksmsbd.net/api/smsapi';
  var finalTpl = tplIn || 'উদ্যোক্তা গ্রাফিক্স AI তে আপনার ওটিপি কোড: {otp}। মেয়াদ ৫ মিনিট।';

  var payload = { senderId: finalSender, url: finalUrl, template: finalTpl };
  if (finalToken) payload.token = finalToken;

  call('a_sms', { sms: payload }, 'BulkSMSBD কনফিগারেশন সেভ হয়েছে ✓').then(function () {
    A.data.settings = null;
    render('settings');
  }).catch(function () {});
};

function translateSmsErr(code, orig) {
  var c = Number(code);
  if (c === 202) return 'সফলভাবে সম্পন্ন হয়েছে।';
  if (c === 1001) return 'ভুল বা অকার্যকর ফোন নম্বর।';
  if (c === 1002) return 'অনুমোদিত সেন্ডার আইডি মেলেনি।';
  if (c === 1003) return 'মেসেজের সাইজ লিমিট অতিক্রম করেছে বা তথ্য অপূর্ণ।';
  if (c === 1005) return 'BulkSMSBD একাউন্ট স্থগিত বা সাসপেন্ড আছে।';
  if (c === 1006) return 'মেসেজের ঘর খালি ছিল।';
  if (c === 1007 || c === 1011) return 'অকার্যকর BulkSMSBD API Key! সঠিক API Key দিন।';
  if (c === 1012) return 'অপর্যাপ্ত ব্যালেন্স! BulkSMSBD একাউন্টে টাকা রিচার্জ করুন।';
  if (c === 1013) return 'সেন্ডার আইডিটি অনুমোদিত (Approved) নয়।';
  return orig || 'গেটওয়ে থেকে ত্রুটি পাওয়া গেছে।';
}

